    vec4 fog=texture(fog_guide,uv);
    vec3 native_tint=mix(fog.rgb,scanout.outline_color,fog.a);
    vec3 outline_color=scanout.input_linear!=0u
        ? oot3d_srgb_to_linear(native_tint) : native_tint;
